begin;
create table if not exists public.ai_employee_definitions(id text primary key,name text not null,role text not null,version text not null,maturity text not null check(maturity in('Production','Conditional','Mock','Locked')),provider text,external_execution_allowed boolean not null default false check(external_execution_allowed=false),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ai_employee_capabilities(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),ai_employee_id text not null references public.ai_employee_definitions(id),capability text not null,service text not null,permission_class text not null,maturity text not null check(maturity in('Production','Conditional','Mock','Locked')),required_scopes text[] not null default '{}',approval_required boolean not null default false,enabled boolean not null default false,quota_units integer not null default 0 check(quota_units>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,ai_employee_id,capability));
create table if not exists public.ai_employee_tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),owner_id uuid not null,ai_employee_id text not null references public.ai_employee_definitions(id),workflow_id text not null,task_key text not null,correlation_id text not null,capability text not null,purpose text not null,status text not null check(status in('draft','validated','dry_run_ready','awaiting_connection','awaiting_scope','awaiting_approval','ready','reserved','running','partial','completed','failed','cancelled','expired')),data_classification text not null check(data_classification in('public','internal','confidential','restricted')),parameters_metadata jsonb not null default '{}',idempotency_key text not null,max_api_calls integer not null check(max_api_calls between 0 and 50),max_records integer not null check(max_records between 0 and 1000),max_duration_ms integer not null check(max_duration_ms between 1 and 30000),cost_ceiling_jpy numeric not null check(cost_ceiling_jpy>=0),approval_id uuid,expires_at timestamptz,retention_until timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,ai_employee_id,idempotency_key),check(not(parameters_metadata ?| array['mail_body','file_body','prompt','access_token','refresh_token','oauth_code','secret'])));
create table if not exists public.ai_employee_task_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),task_id uuid not null references public.ai_employee_tasks(id),event_type text not null,status text not null,normalized_error text,metrics jsonb not null default '{}',created_at timestamptz not null default now(),check(not(metrics ?| array['mail_body','file_body','prompt','access_token','refresh_token','oauth_code','secret'])));
create table if not exists public.ai_employee_handoffs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),source_employee_id text not null,target_employee_id text not null,task_id uuid not null references public.ai_employee_tasks(id),classification text not null,status text not null default 'proposed',field_manifest text[] not null default '{}',raw_content_included boolean not null default false check(raw_content_included=false),created_at timestamptz not null default now());
create table if not exists public.google_workspace_bindings(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),provider_connection_id uuid not null references public.provider_connections(id),expected_account_id text,analytics_property_id text,search_console_site_url text,youtube_channel_id text,state text not null default 'locked',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id));
create table if not exists public.google_quota_policies(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),service text not null,daily_call_limit integer not null default 100 check(daily_call_limit between 0 and 10000),per_task_call_limit integer not null default 10 check(per_task_call_limit between 0 and 50),page_limit integer not null default 10 check(page_limit between 1 and 100),record_limit integer not null default 1000 check(record_limit between 1 and 1000),enabled boolean not null default false,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,service));
create table if not exists public.google_quota_usage(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),service text not null,task_id uuid references public.ai_employee_tasks(id),estimated_units integer not null check(estimated_units>=0),actual_units integer check(actual_units>=0),status text not null check(status in('reserved','committed','released','failed')),usage_date date not null default current_date,created_at timestamptz not null default now());
create index if not exists ai_tasks_workspace_status_idx on public.ai_employee_tasks(workspace_id,status,created_at desc);create index if not exists ai_events_task_created_idx on public.ai_employee_task_events(task_id,created_at);create index if not exists ai_handoffs_workspace_idx on public.ai_employee_handoffs(workspace_id,status);create index if not exists google_quota_workspace_date_idx on public.google_quota_usage(workspace_id,service,usage_date,status);
insert into public.ai_employee_definitions(id,name,role,version,maturity) values('google_operations','Google Operations AI Employee','Google services operations','1.0.0','Conditional') on conflict(id) do nothing;
do $$ declare t text;begin foreach t in array array['ai_employee_capabilities','ai_employee_tasks','ai_employee_task_events','ai_employee_handoffs','google_workspace_bindings','google_quota_policies','google_quota_usage'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists %I on public.%I','ai_employee_owner_read',t);execute format('create policy %I on public.%I for select to authenticated using(exists(select 1 from public.workspace_members wm where wm.workspace_id=%I.workspace_id and wm.user_id=auth.uid() and wm.role=''owner'' and wm.status=''active''))','ai_employee_owner_read',t,t);end loop;end$$;
revoke all on table public.ai_employee_definitions,public.ai_employee_capabilities,public.ai_employee_tasks,public.ai_employee_task_events,public.ai_employee_handoffs,public.google_workspace_bindings,public.google_quota_policies,public.google_quota_usage from public,anon,authenticated;grant select on table public.ai_employee_definitions,public.ai_employee_capabilities,public.ai_employee_tasks,public.ai_employee_task_events,public.ai_employee_handoffs,public.google_workspace_bindings,public.google_quota_policies,public.google_quota_usage to authenticated;grant select,insert,update on table public.ai_employee_capabilities,public.ai_employee_tasks,public.ai_employee_handoffs,public.google_workspace_bindings,public.google_quota_policies,public.google_quota_usage to service_role;grant select,insert on table public.ai_employee_task_events to service_role;
commit;
